def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in set(grid[0]) if v != 0)
    rs = [r for r in range(h) if all(x == sep for x in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    row_starts = [0] + [r + 1 for r in rs]
    col_starts = [0] + [c + 1 for c in cs]

    pattern = None
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            cells = [(r-r0, c-c0) for r in range(r0, min(r0+4, h))
                     for c in range(c0, min(c0+4, w))
                     if grid[r][c] not in (0, sep)]
            if cells and ci != 0:
                pattern = cells
                break
        if pattern is not None:
            break

    out = [[sep if grid[r][c] == sep else 0 for c in range(w)] for r in range(h)]
    for ri, r0 in enumerate(row_starts):
        # The colored marker in the leftmost panel determines this band’s color.
        color = next((grid[r][c] for r in range(r0, min(r0+4, h))
                      for c in range(0, min(4, w)) if grid[r][c] not in (0, sep)), 0)
        if not color:
            continue
        for c0 in col_starts:
            for dr, dc in pattern:
                r, c = r0 + dr, c0 + dc
                if r < h and c < w and out[r][c] != sep:
                    out[r][c] = color
    return out
